 async function login(e:FormEvent<HTMLFormElement>){e.preventDefault();setError('');const form=new FormData(e.currentTarget);try{const r=await request<{user:SessionUser}>('/auth/login',{method:'POST',body:JSON.stringify({tenant:form.get('tenant'),email:form.get('email'),password:form.get('password')})});setUser(r.user)}catch(e){setError((e as Error).message)}}
 function openTableInPos(table:{id:string;label:string}){setTarget(table);setOrderId('');setView('pos');setNotice('')}
 function add(product:Product){setCart(current=>({...current,[product.id]:{quantity:(current[product.id]?.quantity||0)+1,removedIngredientIds:current[product.id]?.removedIngredientIds||[],addedIngredients:current[product.id]?.addedIngredients||[]}}))}
 function changeQuantity(id:string,delta:number){setCart(current=>{const line=current[id];if(!line)return current;const quantity=line.quantity+delta;if(quantity<=0){const next={...current};delete next[id];if(editing===id)setEditing(null);return next}return{...current,[id]:{...line,quantity}}})}
 async function openEditor(product:Product){setEditing(product.id);setExtraId('');setExtraQuantity(1);if(modifierCache[product.id])return;if(DEMO){const base=((product as any).ingredients||[]) as Ingredient[],allowed=((product as any).allowedExtraIds||[]) as string[],available:Ingredient[]=[];for(const key of allowed){const ingredient=demoIngredients.find(i=>i.id===key);if(ingredient)available.push({...ingredient,extraPriceNet:demoExtraPrices[product.id]?.[key]||0})}setModifierCache(cache=>({...cache,[product.id]:{base,available}}));return}try{const modifiers=await request<Modifiers>(`/products/${product.id}/modifiers`);setModifierCache(cache=>({...cache,[product.id]:modifiers}))}catch(e){setError((e as Error).message)}}
 function toggleRemoved(productId:string,ingredientId:string){setCart(current=>{const line=current[productId];if(!line)return current;const removed=line.removedIngredientIds.includes(ingredientId)?line.removedIngredientIds.filter(id=>id!==ingredientId):[...line.removedIngredientIds,ingredientId];return{...current,[productId]:{...line,removedIngredientIds:removed}}})}
 function addExtra(productId:string){if(!extraId)return;if(!Number.isFinite(extraQuantity)||extraQuantity<=0){setError('Indica una cantidad mayor que cero');return}const extraPriceNet=Number(modifierCache[productId]?.available.find(i=>i.id===extraId)?.extraPriceNet||0);setCart(current=>{const line=current[productId];if(!line)return current;return{...current,[productId]:{...line,addedIngredients:[...line.addedIngredients,{ingredientId:extraId,quantity:extraQuantity,extraPriceNet}]}}});setExtraId('');setExtraQuantity(1)}
 function removeExtra(productId:string,index:number){setCart(current=>{const line=current[productId];if(!line)return current;return{...current,[productId]:{...line,addedIngredients:line.addedIngredients.filter((_,i)=>i!==index)}}})}
 async function sendOrder(){if(sending)return;setSending(true);setError('');try{const order=orderId?{id:orderId,reused:true}:await request<{id:string;reused:boolean;orderNumber:number}>('/orders',{method:'POST',body:JSON.stringify(target?{tableId:target.id}:{channel:'counter'})});for(const [productId,line] of Object.entries(cart))await request(`/orders/${order.id}/lines`,{method:'POST',body:JSON.stringify({productId,quantity:line.quantity,removeIngredientIds:line.removedIngredientIds,addedIngredients:line.addedIngredients})});await request(`/orders/${order.id}/send`,{method:'POST'});setNotice(`${target?target.label:'Mostrador'}: ${order.reused?'productos añadidos a la comanda abierta':'comanda enviada a cocina'}.`);setLastSent(order.id);setCart({});setOrderId('');setEditing(null);request<DiningTable[]>('/tables').then(setTableOptions).catch(()=>{})}catch(e){setError((e as Error).message)}finally{setSending(false)}}
