 if(qrToken)return <QrOrdering token={qrToken}/>;
 if(!user)return <main className="login"><form onSubmit={login} className="login-card"><div className="brand-mark">B</div><p className="eyebrow">BAR MANAGER</p><h1>Bienvenido</h1><p className="muted">Accede al espacio de tu local</p><label>Identificador del local<input required name="tenant" placeholder="mi-bar"/></label><label>Email<input required name="email" type="email" placeholder="tu@email.com"/></label><label>Contraseña<input required name="password" type="password"/></label>{error&&<p className="error">{error}</p>}<button className="primary wide">Entrar al sistema</button>{DEMO&&<button type="button" className="secondary wide" onClick={demoLogin}>Entrar como administrador (demo) →</button>}</form></main>;
 const lineGross=(product:Product,line:CartLine)=>(Number(product.priceNet)+line.addedIngredients.reduce((sum,i)=>sum+i.extraPriceNet,0))*(1+product.vatRate/100)*line.quantity;
 const total=Object.entries(cart).reduce((sum,[id,line])=>{const product=products.find(p=>p.id===id);return sum+(product?lineGross(product,line):0)},0);
 const preferred=['Desayunos','Entrantes','Primeros platos','Segundos platos','Postres','Bebidas'];const present=[...new Set(products.map(menuSection))];const sections=[...preferred.filter(x=>present.includes(x)),...present.filter(x=>!preferred.includes(x)).sort()];const shownSections=menuCategory==='Todas'?sections:sections.filter(x=>x===menuCategory);
 return <div className="app-shell"><aside className="sidebar"><div className="logo"><span className="brand-mark small">B</span><strong>barra<span>OS</span></strong></div><div className="tenant"><span className="tenant-dot"/>{user.tenantName}<small>Espacio de trabajo</small></div><nav><button className={view==='tables'?'active':''} onClick={()=>setView('tables')}>◫ <span>Mapa de mesas</span></button><button className={view==='pos'?'active':''} onClick={()=>setView('pos')}>▦ <span>TPV y comandas</span></button><button className={view==='orders'?'active':''} onClick={()=>setView('orders')}>▣ <span>Pedidos y cobros</span></button>{canUseKitchen&&<button className={view==='kitchen'?'active':''} onClick={()=>setView('kitchen')}>♨ <span>Cocina</span></button>}{canManage&&<><button className={view==='menu'?'active':''} onClick={()=>setView('menu')}>☰ <span>Carta</span></button><button className={view==='staff'?'active':''} onClick={()=>setView('staff')}>♙ <span>Equipo temporal</span></button></>}<button className={view==='inventory'?'active':''} onClick={()=>setView('inventory')}>◈ <span>Inventario</span></button><button className={view==='finance'?'active':''} onClick={()=>{setView('finance');void getReport()}}>▤ <span>Finanzas</span></button></nav><div className="side-bottom"><div className="avatar">{user.fullName.slice(0,1).toUpperCase()}</div><div>{user.fullName}<small>{user.role}</small></div><button className="logout" onClick={()=>DEMO?setUser(null):request('/auth/logout',{method:'POST'}).then(()=>setUser(null))}>↗</button></div></aside>
  <main className="main"><header className="topbar"><div><span className="eyebrow">PANEL DE CONTROL</span><h2>{({tables:'Mapa de mesas',pos:'TPV y comandas',orders:'Pedidos y cobros',menu:'Carta',inventory:'Inventario',finance:'Finanzas',kitchen:'Cocina',staff:'Equipo temporal'} as const)[view]}</h2></div><div className="today">● <span>Servicio activo</span></div></header>{error&&<div className="toast" onClick={()=>setError('')}>{error} ×</div>}
   {view==='pos'&&<div className="content-grid"><section><div className="section-head"><div><h3>Carta</h3><p>Platos organizados por tipo</p></div><span className="pill">{products.length} productos</span></div><div className="menu-category-tabs"><button className={menuCategory==='Todas'?'selected':''} onClick={()=>setMenuCategory('Todas')}>Todas</button>{sections.map(section=><button key={section} className={menuCategory===section?'selected':''} onClick={()=>setMenuCategory(section)}>{section}</button>)}</div>{shownSections.map(section=><div className="menu-section" key={section}><div className="menu-section-title"><h3>{section}</h3><span>{products.filter(p=>menuSection(p)===section).length}</span></div><div className="product-grid">{products.filter(p=>menuSection(p)===section).map(p=><button className="product-card" key={p.id} onClick={()=>void add(p)}><span className="product-icon">✳</span><span className="product-name">{p.name}</span><span className="product-cat">{section}</span><strong>{(p.priceNet*(1+p.vatRate/100)).toFixed(2)} €</strong><span className="add-product">+</span></button>)}</div></div>)}</section>
    <aside className="order-panel"><div className="section-head"><div><h3>Comanda actual</h3><p>{target?(tableOptions.find(t=>t.id===target.id)?.activeOrder?`Se añadirá a la comanda #${tableOptions.find(t=>t.id===target.id)!.activeOrder!.orderNumber}`:'Nueva comanda de mesa'):'Venta en mostrador'}</p></div><span className="live-dot"/></div><label className="destination"><span>Destino</span><select value={target?.id||''} onChange={e=>{const t=tableOptions.find(x=>x.id===e.target.value);setTarget(t?{id:t.id,label:t.label}:null);setOrderId('')}}><option value="">Mostrador / para llevar</option>{[...new Set(tableOptions.map(t=>t.zone))].map(z=><optgroup key={z} label={z}>{tableOptions.filter(t=>t.zone===z).map(t=><option key={t.id} value={t.id}>{t.label}{t.activeOrder?` · ocupada (${euro(Number(t.activeOrder.grossTotal)-Number(t.activeOrder.paidTotal))})`:' · libre'}</option>)}</optgroup>)}</select></label>{notice&&<div className="order-notice pos-notice">✓ {notice}{lastSent&&<button className="text-button" onClick={()=>setPaying(lastSent)}>Cobrar ahora</button>}{target&&<button className="text-button" onClick={()=>setView('tables')}>Ver mapa</button>}</div>}<div className="cart-lines">{Object.entries(cart).map(([id,line])=>{const p=products.find(x=>x.id===id);if(!p)return null;const mods=modifierCache[id];const customization=[...line.removedIngredientIds.map(i=>`Sin ${mods?.base.find(x=>x.id===i)?.name||'ingrediente'}`),...line.addedIngredients.map(i=>`+ ${mods?.available.find(x=>x.id===i.ingredientId)?.name||'extra'} (+${(i.extraPriceNet*(1+p.vatRate/100)).toFixed(2)} €)`)];const gross=lineGross(p,line);return <div className="cart-entry" key={id}><div className="cart-line"><div><strong>{p.name}</strong><small>{line.quantity} × {(gross/line.quantity).toFixed(2)} €</small>{customization.length>0&&<small className="customization-summary">{customization.join(' · ')}</small>}</div><strong>{gross.toFixed(2)} €</strong></div><div className="cart-actions"><div className="quantity-control"><button onClick={()=>changeQuantity(id,-1)} aria-label="Quitar unidad">−</button><span>{line.quantity}</span><button onClick={()=>changeQuantity(id,1)} aria-label="Añadir unidad">+</button></div><button className="text-button" onClick={()=>void openEditor(p)}>{line.removedIngredientIds.length||line.addedIngredients.length?'Editar ingredientes':'Ingredientes'}</button><button className="remove-button" onClick={()=>changeQuantity(id,-line.quantity)}>Quitar</button></div>
      {editing===id&&mods&&<div className="modifier-editor"><div className="modifier-title">Personalizar {p.name}</div><p>Desmarca para retirar; añade extras compatibles con recargo.</p><div className="modifier-list">{mods.base.map(i=><label className="ingredient-check" key={i.id}><input type="checkbox" checked={!line.removedIngredientIds.includes(i.id)} onChange={()=>toggleRemoved(id,i.id)}/><span>{i.name}</span><small>{i.quantityPerUnit}{i.unit} por plato</small></label>)}</div><div className="add-ingredient"><select value={extraId} onChange={e=>{const selected=e.target.value;setExtraId(selected);const chosen=mods.available.find(i=>i.id===selected);setExtraQuantity(chosen?.quantityPerUnit||(chosen?.unit==='ud'?1:10))}}><option value="">Añadir ingrediente…</option>{mods.available.map(i=><option value={i.id} key={i.id}>{i.name} · +{((i.extraPriceNet||0)*(1+p.vatRate/100)).toFixed(2)} €</option>)}</select><input aria-label="Cantidad ingrediente" type="number" min="0.001" step="0.001" value={extraQuantity} onChange={e=>setExtraQuantity(Number(e.target.value))}/><button className="secondary" onClick={()=>addExtra(id)}>Añadir</button></div>{line.addedIngredients.map((extra,index)=>{const ingredient=mods.available.find(i=>i.id===extra.ingredientId);return <div className="extra-line" key={`${extra.ingredientId}-${index}`}><span>+ {ingredient?.name} · {extra.quantity} {ingredient?.unit} · +{(extra.extraPriceNet*(1+p.vatRate/100)).toFixed(2)} €</span><button onClick={()=>removeExtra(id,index)}>×</button></div>})}<button className="done-editing" onClick={()=>setEditing(null)}>Listo</button></div>}</div>})}{!Object.keys(cart).length&&<div className="empty-cart">Añade productos desde la carta</div>}</div><div className="order-total"><span>Total estimado</span><strong>{total.toFixed(2)} €</strong></div><button className="primary wide" onClick={()=>void sendOrder()} disabled={!Object.keys(cart).length||sending}>{sending?'Enviando…':target?`Enviar · ${target.label}`:'Enviar a cocina'} <span>→</span></button><p className="hint">Puedes editar cantidades e ingredientes antes de enviar</p></aside></div>}
   {view==='staff'&&canManage&&<TemporaryStaff/>}{view==='tables'&&user.role!=='kitchen'&&<TablesView canEdit={canManage} onOpenInPos={openTableInPos}/>}{view==='orders'&&user.role!=='kitchen'&&<OrdersView products={products}/>}{view==='kitchen'&&canUseKitchen&&<KitchenView/>}{view==='menu'&&canManage&&<MenuAdmin onChanged={loadMenu}/>}{paying&&<PaymentModal orderId={paying} onClose={()=>setPaying('')} onPaid={closed=>{if(closed){setLastSent('');setNotice('Comanda cobrada.');request<DiningTable[]>('/tables').then(setTableOptions).catch(()=>{})}}}/>}{view==='inventory'&&<Inventory/>}{view==='finance'&&<Finance report={report} period={financePeriod} date={financeDate} onPeriod={p=>{setFinancePeriod(p);void getReport(p,financeDate)}} onDate={d=>{setFinanceDate(d);void getReport(financePeriod,d)}} refresh={()=>void getReport()}/>}
  </main></div>
