 function changePending(productId:string,delta:number){setPending(current=>{const quantity=(current[productId]||0)+delta;if(quantity<=0){const next={...current};delete next[productId];return next}return{...current,[productId]:quantity}})}
 async function addToOrder(){if(!selected||!Object.keys(pending).length||saving)return;setSaving(true);setError('');setNotice('');try{for(const [productId,quantity] of Object.entries(pending))await request(`/orders/${selected.id}/lines`,{method:'POST',body:JSON.stringify({productId,quantity})});await request(`/orders/${selected.id}/send`,{method:'POST'});const detail=await request<any>(`/orders/${selected.id}`);setSelected(detail);setPending({});const rows=await request<any[]>('/orders/active');setOrders(rows);setNotice('Ampliación enviada a cocina.')}catch(e){setError((e as Error).message)}finally{setSaving(false)}}
